import { validateGame } from './game-model.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function sketchSvg(sketch){return `<svg viewBox="0 0 120 120" role="img" aria-label="Concept board sketch">${sketch.map(s=>{let shape;const x=s.x+10,y=s.y+10;if(s.shape==='circle')shape=`<circle cx="${x}" cy="${y}" r="${s.size/2}"/>`;else if(s.shape==='square')shape=`<rect x="${x-s.size/2}" y="${y-s.size/2}" width="${s.size}" height="${s.size}" rx="1"/>`;else shape=`<polygon points="${Array.from({length:6},(_,i)=>{const a=i*Math.PI/3;return [x+Math.sin(a)*s.size/2,y+Math.cos(a)*s.size/2].join(',');}).join(' ')}"/>`;return `<g fill="${esc(s.color)}" stroke="#112019" stroke-width=".6">${shape}<text x="${x}" y="${y+1}" text-anchor="middle" font-size="3" fill="#132019" stroke="none">${esc(s.label)}</text></g>`;}).join('')}</svg>`;}
export function installDesignChat({getContext,captureView,onPreview,onApply,onDiscard}){
 const root=document.querySelector('#design-chat'),gallery=document.querySelector('#concept-gallery');
 let messages=[],busy=false,controller=null,pending=null,base=null,configured=false,model='gpt-6-astra',turn=0;
 root.innerHTML=`<header class="chat-heading"><div><div class="eyebrow">DESIGN ASSISTANT</div><h2>Conversation</h2></div><button id="chat-reset" title="Clear conversation" aria-label="Clear conversation">↺</button></header><div id="connection" role="status">Checking connection…</div><div class="chat-messages" id="chat-messages" role="log" aria-label="Design conversation"></div><div class="selection-context" id="selection-context"></div><form id="chat-form"><label class="sr-only" for="chat-input">Message your game designer</label><textarea id="chat-input" maxlength="5000" placeholder="Describe a game or request an edit…" rows="3"></textarea><div class="vision-controls"><label><input type="checkbox" id="include-view" checked> Include viewport</label><button id="review-view" type="button">Review view</button></div><div class="composer-actions"><span id="chat-hint">Enter to send · Shift+Enter for a new line</span><button id="chat-stop" type="button" hidden>Stop</button><button id="chat-send" class="primary" aria-label="Send message">↑</button></div></form><p class="chat-footnote">AI suggestions need playtesting. Changes are previewed before applying.</p>`;
 const $=id=>document.getElementById(id);
 async function connect(){try{const r=await fetch('/api/status',{cache:'no-store'});if(!r.ok)throw Error();const s=await r.json();configured=s.configured;model=s.model;$('connection').innerHTML=configured?`<span class="connected">Subscription · ${esc(model)}</span>`:'<span>Codex sign-in needed</span><button id="reconnect">Reconnect</button><p>Run codex login and sign in with ChatGPT, then reconnect. API keys are disabled.</p>';document.querySelector('#reconnect')?.addEventListener('click',connect);}catch{configured=false;$('connection').innerHTML='<span>AI server unavailable</span><button id="reconnect">Retry</button><p>Start the project with npm run dev to use the design conversation.</p>';document.querySelector('#reconnect')?.addEventListener('click',connect);}}
 function render(){
  $('chat-messages').innerHTML=messages.length?messages.map((m,i)=>`<article class="chat-message ${m.role}"><div class="message-author">${m.role==='user'?'YOU':m.role==='assistant'?'ASSISTANT':'STUDIO'}</div><div class="message-text">${esc(m.text)}</div>${m.reply?.critique?.length?`<div class="design-review"><strong>Design checks · not playtest results</strong>${m.reply.critique.map(c=>`<div><b>${esc(c.issue)}</b><p>${esc(c.check)}</p></div>`).join('')}</div>`:''}${m.reply?.concepts?.length?`<button class="show-concepts" data-show="${i}">Explore ${m.reply.concepts.length} visual directions ↗</button>`:''}${i===messages.length-1&&m.reply?.suggestions?.length?`<div class="reply-options">${m.reply.suggestions.map((s,j)=>`<button data-suggestion="${j}">${esc(s)}</button>`).join('')}</div>`:''}</article>`).join(''):`<div class="chat-welcome"><h3>New conversation</h3><p>Describe your concept, compare mechanics, or request changes to the current selection.</p><button id="last-light-example">Preview Last Light game</button><button id="observatory-example">Preview observatory study</button><button data-start="Help me explore a cooperative game where we run a chaotic restaurant.">Develop a cooperative game</button><button data-start="Show me three different directions for a 20-minute game about time travel.">Compare design directions</button><button data-start="I have a game idea. Help me test whether its core mechanic makes sense.">Review a game mechanic</button></div>`;
  if(busy)$('chat-messages').insertAdjacentHTML('beforeend','<div class="chat-thinking" role="status">Thinking through your game…</div>');
  $('chat-send').disabled=busy;$('chat-input').disabled=busy;$('chat-stop').hidden=!busy;
  $('observatory-example')?.addEventListener('click',()=>loadExample('observatory'));
  $('last-light-example')?.addEventListener('click',()=>loadExample('last-light'));
  root.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>submit(b.dataset.start));
  root.querySelectorAll('[data-show]').forEach(b=>b.onclick=()=>showConcepts(messages[+b.dataset.show].reply.concepts));
  root.querySelectorAll('[data-suggestion]').forEach(b=>b.onclick=()=>submit(messages.at(-1).reply.suggestions[+b.dataset.suggestion]));
  $('chat-messages').scrollTop=$('chat-messages').scrollHeight;
 }
 function showConcepts(concepts){gallery.hidden=false;gallery.innerHTML=`<header><div><div class="eyebrow">CONCEPT REVIEW</div><h2>Design alternatives</h2></div><button id="close-concepts" aria-label="Close visual directions">✕</button></header><div class="concept-cards">${concepts.map((c,i)=>`<article class="concept-choice">${sketchSvg(c.sketch)}<div class="eyebrow">DIRECTION 0${i+1}</div><h3>${esc(c.title)}</h3><p>${esc(c.summary)}</p><p class="concept-tradeoff">${esc(c.tradeoff)}</p><button data-choose="${i}" class="primary">Select direction</button></article>`).join('')}</div><p class="concept-footer">Choose one, or ask to combine elements in the conversation. These are layout sketches.</p>`;
  $('close-concepts').onclick=()=>gallery.hidden=true;
  gallery.querySelectorAll('[data-choose]').forEach(b=>b.onclick=()=>{const c=concepts[+b.dataset.choose];gallery.hidden=true;submit('I like this direction: '+c.title+'. '+c.summary+' Tradeoff: '+c.tradeoff+'. Help me refine it, or build it if you have enough information.');});
 }
 function proposalBar(){let bar=document.querySelector('#proposal-bar');if(!bar){bar=document.createElement('div');bar.id='proposal-bar';document.querySelector('.viewport').append(bar);}bar.innerHTML=`<div><div class="eyebrow">PROPOSED CHANGE · NOT APPLIED</div><strong>${esc(pending.summary)}</strong><span>${pending.game.objects.length} components · ${esc(pending.game.name)}</span></div><button id="discard-proposal">Discard</button><button id="apply-proposal" class="primary">Apply to game</button>`;
  $('discard-proposal').onclick=()=>clearProposal();
  $('apply-proposal').onclick=()=>{if(JSON.stringify(getContext().game)!==base){messages.push({role:'notice',text:'Your game changed after this proposal was requested. Ask me to revise against the latest board so your manual edits are preserved.'});clearProposal();render();return;}onApply(pending.game);messages.push({role:'notice',text:'Applied: '+pending.summary+'. Undo in the editor will restore the previous game.'});pending=null;base=null;bar.remove();render();};
 }
 function clearProposal(){pending=null;base=null;document.querySelector('#proposal-bar')?.remove();onDiscard();}
 async function submit(text){if(busy||!text.trim())return;if(text.length>5000)return;
  if(pending)clearProposal();gallery.hidden=true;messages.push({role:'user',text});$('chat-input').value='';busy=true;controller=new AbortController();const thisTurn=++turn;const context=getContext(),snapshot=JSON.stringify(context.game);let viewportImage=null;try{if($('include-view').checked)viewportImage=captureView?.()??null;}catch{}render();
  const history=messages.filter(m=>m.role==='user'||m.role==='assistant').slice(-40).map(m=>({role:m.role,content:m.text+(m.reply?'\nDesign context: '+JSON.stringify({concepts:m.reply.concepts,critique:m.reply.critique,proposalSummary:m.reply.proposal?.summary??null}):'')}));
  try{const r=await fetch('/api/design',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...context,viewportImage,messages:history}),signal:controller.signal});let reply;try{reply=await r.json();}catch{throw Error('AI server unavailable. Start the project with npm run dev.');}if(!r.ok)throw Error(reply.error||'The design request failed.');if(thisTurn!==turn)return;
   if(reply.proposal)reply.proposal.game=validateGame(reply.proposal.game);
   messages.push({role:'assistant',text:reply.message,reply});if(reply.proposal){pending=reply.proposal;base=snapshot;onPreview(pending.game);proposalBar();}else if(reply.concepts.length)showConcepts(reply.concepts);
  }catch(e){if(thisTurn===turn){messages.push({role:'notice',text:e.name==='AbortError'?'Request stopped. Your game is unchanged.':e.message});$('chat-input').value=text;}}finally{if(thisTurn===turn){busy=false;controller=null;render();selectionChanged();}}
 }
 async function loadExample(name){
  if(!['observatory','last-light'].includes(name))return;
  if(busy)return;
  try{const response=await fetch('/examples/'+name+'.json');if(!response.ok)throw Error('This example is not available yet.');const draft=validateGame(await response.json());
   clearProposal();base=JSON.stringify(getContext().game);pending={summary: name==='observatory'?'Floating observatory · editable geometry study':'Last Light · printable two-player prototype',game:draft};
   messages.push({role:'notice',text:name==='observatory'?'Observatory study generated with Astra through Codex using ChatGPT sign-in. Preview its editable parts, then apply or discard. This is a geometry study, not a complete playable game.':'Last Light was generated with Astra through Codex using ChatGPT sign-in. Apply to inspect the rules, try the tabletop, or print the kit. This prototype still needs human playtesting.'});
   onPreview(draft);proposalBar();render();
  }catch(e){messages.push({role:'notice',text:e.message});render();}
 }
 function selectionChanged(){const c=getContext(),o=c.game.objects.find(o=>o.id===c.selectedId);$('selection-context').textContent=o?'Selection: '+o.name+' · '+o.type:'Context: Entire project';}
 function reset(){if(busy)controller?.abort();turn++;busy=false;messages=[];gallery.hidden=true;clearProposal();render();selectionChanged();}
 $('review-view').onclick=()=>{if(!$('include-view').checked)$('include-view').checked=true;submit('Review the attached viewport for composition, crowding, scale, visual clarity and readability. Give specific improvements; do not change the game yet.');};
 $('chat-form').onsubmit=e=>{e.preventDefault();submit($('chat-input').value);};$('chat-input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();submit(e.target.value);}};$('chat-stop').onclick=()=>controller?.abort();$('chat-reset').onclick=()=>{if(messages.length&&!confirm('Clear this design conversation? The board will stay unchanged.'))return;reset();};
 render();selectionChanged();connect();loadExample(new URLSearchParams(location.search).get('example'));return {reset,selectionChanged,submit,connect,clearProposal};
}
